function countFreq(text, opts){
  opts=opts||{}; var mode=opts.mode||'word';
  var top=opts.top!=null?opts.top:10; if(top<1) top=1;
  var t=String(text||'');
  var items;
  if(mode==='line') items=t.split(/\r?\n/).map(function(s){ return s.replace(/^\s+|\s+$/g,''); }).filter(Boolean);
  else items=(t.toLowerCase().match(/[a-z0-9]+|[一-龥]+/g)||[]);
  var freq={};
  for(var i=0;i<items.length;i++){ freq[items[i]]=(freq[items[i]]||0)+1; }
  var keys=[]; for(var k in freq) keys.push(k);
  keys.sort(function(a,b){ return (freq[b]-freq[a]) || (a<b?-1:(a>b?1:0)); });
  var picked=keys.slice(0,top);
  var out=[]; var rows=[];
  for(var j=0;j<picked.length;j++){ rows.push({key:picked[j], count:freq[picked[j]]}); out.push(picked[j]+'\t'+freq[picked[j]]); }
  return {ok:true, items:rows, text:out.join('\n'), total:items.length, unique:keys.length};
}

var EXPORTS={countFreq:countFreq};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CountForgePure = EXPORTS; }
